#include <math.h>

/* os cartazes da biblioteca — o que iria no ponto.h */
double distancia(double ax, double ay, double bx, double by);
double areaRetangulo(double largura, double altura);

/* as caixas da biblioteca — o que iria no ponto.c */
double distancia(double ax, double ay, double bx, double by) {
    double dx = bx - ax;
    double dy = by - ay;
    return sqrt(dx * dx + dy * dy);
}

double areaRetangulo(double largura, double altura) {
    return largura * altura;
}
